INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Tarjeta BCARD','Permite efectuar compras en cualquier tienda (física o virtual) que pertenece al Retail y en cualquier tienda adherida. Ademas permite solicitar Avances y Súper Avances de Dinero',NULL,NULL);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Crédito de Consumo','Crédito para financiar la compra de bienes de consumo o realizar el pago de servicios destinado a socios que acrediten renta mínima de $900.000 mensual. El tope del crédito es de $5.000.000',0.50,72);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Crédito Automotriz','Crédito para la adquisición de vehículo nuevo o usado destinado a trabajadores (dependientes o independientes) que acrediten renta mínima de $900.000 mensual. El tope del crédito es de $10.000.000',0.4,60);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Crédito de Emergencia','Crédito para solucionar un imprevisto de salud o catástrofe destinado a los socios que acrediten renta mínima de $900.000 mensual (para trabajadores) o una pensión mínima de $150.000 mensual (para pensionados o tercera edad). El tope del crédito es de $1.000.000 para trabajadores y de $300.000 para pensionados o tercera edad',0.35,48);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'SOAP','Seguro Obligatorio de Accidentes Personales (SOAP)',NULL,NULL);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Seguro de Vida','Seguro de protección que si al final del periodo contratado no se ha se devuelve un porcentaje de lo pagado en UF',NULL,NULL);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Seguro de Salud','Seguro de protección ante un futuro cáncer y luego de 5 años, en caso de no haberse usado, se le bonifica en UF',NULL,NULL);
INSERT INTO PRODUCTO VALUES(SEQ_PRODUCTO.NEXTVAL,'Seguro de Hogar','Seguro de hogar que puede proteger en forma parcial o completa cualquier problema de infraestructura y/o sinistro',NULL,NULL);
INSERT INTO TIPO_TRANSACCION_TARJETA VALUES(SEQ_TP_TRANSAC_TARJETA.NEXTVAL,'Compras Tiendas Retail o Asociadas',0.05,48,1);
